// Real encrypted archive bytes and signed own roster; availability fixture only.
import assert from 'node:assert/strict';
import {Engine,memoryStore} from '../static/engine.mjs';
import * as wire from '../static/wire.mjs';
const e=new Engine({store:memoryStore(),base:'https://fixture.invalid',fetch:async()=>new Response(JSON.stringify({state:'custody'}))});
e.keys=await wire.newKeys();e.address='owner/desk';e.pub=await wire.publicEntry(e.keys,e.address);e.fp=await wire.fingerprint(e.pub);
const phoneKeys=await wire.newKeys(),phone=await wire.publicEntry(phoneKeys,'owner/phone'),phoneFP=await wire.fingerprint(phone);
const first=await wire.newRoster(e.keys,e.address,'Fixture owner'),next=await wire.nextRoster(e.keys,e.address,first,[e.pub,phone],await wire.joinConsent(phoneKeys,phone.address,first.person,1,await wire.rosterHash(first)),first.label,[e.fp,phoneFP]);
e.me=await e.personRecord([first,next],'self',null);
await e.store.write([{s:'kv',k:'person',v:e.me},{s:'kv',k:'identity',v:{keys:e.keys,address:e.address,fingerprint:e.fp}},...e.me.devices.map(d=>({s:'pins',k:d.address,v:{address:d.address,json:d.json,fingerprint:d.fingerprint,pending:null}}))]);
e.connected=true;e.queueOutbox=()=>{};e.changed=()=>{};e.runHistory=async()=>{};e.uploadBlob=async()=>{};e.supports=async()=>[true,'',false];
let available=true;
e.ctlSupport=async(_address,_pin,cap)=>[cap!==wire.CapTopicContext||available,'peer_update: tpc1 required'];
const root=await wire.newRoot(e.keys,{person:e.me.person,roster:e.me.hash,address:e.address,fingerprint:e.fp},{person:wire.newID(),roster:'c'.repeat(64)}),conv=await wire.rootID(root),pid=wire.newID(),ref={lid:wire.newID(),fingerprint:e.fp};
const event=await wire.signEvent(e.keys,{conv,pid,type:'invite',ts:1,author:{person:e.me.person,roster:e.me.hash,address:e.address,fingerprint:e.fp},host:{person:e.me.person,address:e.address,fingerprint:e.fp},audience:'conversation',topic:wire.newID(),grant:[ref],snapshots:[{...ref,hash:'b'.repeat(64)}]});
const item={v:1,id:wire.newID(),lid:wire.newID(),from:e.address,from_key:e.fp,ts:1,at:1000,kind:'message',pid,sub:'event',body:wire.eventJSON(event),attachments:[]},id=wire.newID(),body=wire.historyJSON(item);
const envelope=await wire.seal({v:2,id,lid:wire.newID(),from:e.address,to:phone.address,ts:1,kind:'message',conv,root:wire.rootJSON(root),sub:'history',body,replica:true},e.keys,phone);
const child={id,to:phone.address,recipient_fp:phoneFP,conv,sub:'history',body,envelope,at:1000,state:'archive_staged',archive_chunk:''};
await e.store.write([{s:'outbox',k:id,v:child}]);
await e.archives().wake();
let jobs=await e.store.prefix('kv','history-archive/out/'),job=jobs[0];
assert.equal(job.required_cap,wire.CapTopicContext);
const firstDescriptor=await e.store.get('outbox',job.id);
await e.store.write([{s:'outbox',k:id,v:{...await e.store.get('outbox',id),body:''}},{s:'outbox',k:job.id,v:{...firstDescriptor,state:'expired'}}]);
await e.archives().receipt({...firstDescriptor,state:'expired'});await e.archives().wake();
jobs=await e.store.prefix('kv','history-archive/out/');job=jobs.find(j=>j.id!==firstDescriptor.id);
assert.equal(job.required_cap,wire.CapTopicContext);
const descriptor=await e.store.get('outbox',job.id),sealed=descriptor.envelope;
assert.equal((await e.store.get('outbox',id)).envelope,envelope);
available=false;await e.post({...descriptor});
assert.equal((await e.store.get('outbox',job.id)).state,'waiting');
assert.equal((await e.store.get('outbox',job.id)).envelope,sealed);
available=true;await e.post({...descriptor,state:'queued'});
assert.equal((await e.store.get('outbox',job.id)).envelope,sealed);
assert.equal((await e.store.get('outbox',job.id)).state,'custody');
console.log('Browser snapshot archive: body erasure, repack, independent waiting and same sealed ciphertext release passed');
// A shared-title child keeps its independent reader gate after plaintext loss,
// restart, expiry and repack; org/mention and base requirements remain present.
let titleAvailable=true;
e.ctlSupport=async(_address,_pin,cap)=>[cap!==wire.CapSharedTopicTitle||titleAvailable,'peer_update: ttl1 required'];
const rename={v:1,id:wire.newID(),lid:wire.newID(),from:e.address,from_key:e.fp,ts:1,at:2000,kind:'message',body:'',topic:wire.newID(),topic_event:{action:'rename',title:'Shared archive title',rev:1},attachments:[]};
const renameID=wire.newID(),renameBody=wire.historyJSON(rename),renameEnvelope=await wire.seal({v:2,id:renameID,lid:wire.newID(),from:e.address,to:phone.address,ts:1,kind:'message',conv,root:wire.rootJSON(root),sub:'history',body:renameBody,replica:true},e.keys,phone);
const renameChild={id:renameID,to:phone.address,recipient_fp:phoneFP,conv,sub:'history',body:renameBody,envelope:renameEnvelope,at:2000,state:'archive_staged',archive_chunk:'',mention_cap:true,organization_cap:true};
Object.assign(renameChild,wire.retainedAgentActionRequirements(renameChild));assert.equal(renameChild.shared_title_cap,true);
await e.store.write([{s:'outbox',k:renameID,v:renameChild}]);await e.archives().wake();
const titleJob=(await e.store.prefix('kv','history-archive/out/')).find(j=>j.children.includes(renameID));assert.equal(titleJob.shared_title_cap,true);
const titleDescriptor=await e.store.get('outbox',titleJob.id);assert.equal(titleDescriptor.shared_title_cap,true);
await e.store.write([{s:'outbox',k:renameID,v:{...await e.store.get('outbox',renameID),body:'',shared_title_cap:false}},{s:'outbox',k:titleJob.id,v:{...titleDescriptor,state:'expired'}}]);
const restarted=new Engine({store:e.store,base:e.base,fetch:e.fetch});for(const k of ['keys','address','pub','fp','me','connected','queueOutbox','changed','runHistory','uploadBlob','supports','ctlSupport'])restarted[k]=e[k];
await restarted.archives().wake();
const repacked=(await e.store.prefix('kv','history-archive/out/')).find(j=>j.id!==titleJob.id&&j.children.includes(renameID));assert.ok(repacked);assert.equal(repacked.shared_title_cap,true);assert.equal(repacked.mention_cap,true);assert.equal(repacked.organization_cap,true);
const retained=await e.store.get('outbox',repacked.id);assert.equal(retained.shared_title_cap,true);assert.equal((await e.store.get('outbox',renameID)).shared_title_cap,true);assert.equal((await e.store.get('outbox',renameID)).envelope,renameEnvelope);
titleAvailable=false;await restarted.post({...retained});assert.equal((await e.store.get('outbox',retained.id)).state,'waiting');
titleAvailable=true;await restarted.post({...retained,state:'queued'});assert.equal((await e.store.get('outbox',retained.id)).state,'custody');assert.equal((await e.store.get('outbox',retained.id)).envelope,retained.envelope);
console.log('Browser shared-title archive: durable independent gate, body loss, restart, repack and exact ciphertext release passed');
